-- Idempotently complete English text for pre-existing auto-ID product Knowledge rows.
UPDATE ENTITIES SET CONTENT=CONTENT||' Chuanxu is a database-authoritative enterprise platform for deploying, operating, governing, and coordinating AI Agents. This Development Candidate requires independent human review.' WHERE ENTITY_TYPE='KNOWLEDGE' AND TITLE LIKE '川序 v4.4.13 平台总览%' AND CONTENT NOT LIKE '%database-authoritative enterprise platform%';
UPDATE ENTITIES SET CONTENT=CONTENT||' Portal checks both principals, retrieves only shared authorized Knowledge, and uses an approved LLM for cited answers. Policy may allow a clearly labeled general-model answer when no Knowledge matches.' WHERE ENTITY_TYPE='KNOWLEDGE' AND TITLE LIKE '川序 v4.4.13 Portal 与知识增强问答%' AND CONTENT NOT LIKE '%Portal checks both principals%';
UPDATE ENTITIES SET CONTENT=CONTENT||' Humans and Agents are governed principals. Roles, delegations, organizations, Security Domains, registration, MFA, approvals, audit, and fail-closed checks protect access.' WHERE ENTITY_TYPE='KNOWLEDGE' AND TITLE LIKE '川序 v4.4.13 身份权限与安全治理%' AND CONTENT NOT LIKE '%Humans and Agents are governed principals%';
UPDATE ENTITIES SET CONTENT=CONTENT||' Chuanxu governs Agent Pool assignment, Tasks, Workspaces, Branches, Loops, Channels, Action Cards, Skills, and Tools.' WHERE ENTITY_TYPE='KNOWLEDGE' AND TITLE LIKE '川序 v4.4.13 Agent 协作与工作管理%' AND CONTENT NOT LIKE '%Chuanxu governs Agent Pool assignment%';
UPDATE ENTITIES SET CONTENT=CONTENT||' Unified entities and edges preserve Knowledge, Memory, Specs, Agents, approvals, relationships, audit, diagnostics, and lease-fencing recovery evidence.' WHERE ENTITY_TYPE='KNOWLEDGE' AND TITLE LIKE '川序 v4.4.13 数据模型、审计与运维%' AND CONTENT NOT LIKE '%Unified entities and edges preserve%';
UPDATE ENTITIES SET CONTENT=CONTENT||' This database adapter provides independent Agent identities, authorization, transactions, Knowledge, Portal, audit, and governance through the common Chuanxu API.' WHERE ENTITY_TYPE='KNOWLEDGE' AND TITLE LIKE '川序 v4.4.13 Oracle Enterprise 数据库能力%' AND CONTENT NOT LIKE '%This database adapter provides%';

